        "summary": "Risoluzione bug nel monorepo",
        "status": {
          "name": "In Progress"
        },
        "assignee": {
          "displayName": "Luca Brognara"
        },
        "duedate": "2023-03-20T14:30:00.000+0000"
      }
    },
    {
      "key": "MONR-2",
      "fields": {
        "summary": "Ottimizzazione delle dipendenze",
        "status": {
          "name": "To Do"
        },
        "assignee": null,
        "duedate": null
      }
    }
  ],
  "formattedList": "[MONR-1](https://jira.example.com/browse/MONR-1) - Risoluzione bug nel monorepo (In Progress, assegnato a Luca Brognara, scadenza: 20 marzo 2023)\n[MONR-2](https://jira.example.com/browse/MONR-2) - Ottimizzazione delle dipendenze (To Do)"
